n = int(input())
mid = n // 2

for i in range(n):
    if i <= mid:
        count = i + 1
    else:
        count = n - i

    for j in range(1, count + 1):
        print(j, end="")
    for j in range(count, 0, -1):
        print(j, end="")
    print()

s = input().strip()

counts = {}
for ch in s:
    counts[ch] = counts.get(ch, 0) + 1

ans = "-1"
for ch in s:
    if counts[ch] > 1:
        ans = ch
        break

print(ans)

